  /* Teal · PANTONE 7717 C */
  --bt-palette-teal-10: #cce8e6;
  --bt-palette-teal-20: #99d1cc;
  --bt-palette-teal-30: #66b9b3;
  --bt-palette-teal-40: #33a299;
  --bt-palette-teal-50: #008b80;
