  /* Neutral Black · Neutral Black C */
  --bt-palette-neutral-black-10: #d2d3d5;
  --bt-palette-neutral-black-20: #a5a7ab;
  --bt-palette-neutral-black-30: #797a81;
  --bt-palette-neutral-black-40: #4c4e57;
  --bt-palette-neutral-black-50: #1f222d;
